        # the crutch "and"/"like" (cut only when pause-adjacent — see the
        # CONTEXT_FILLERS guard in detect_edit_cuts).
        pause_threshold=0.5,
        filler_words=_CORE_FILLERS | _DEFAULT_CRUTCH_FILLERS,
